function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // character
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 70);
  ctx.stroke();

  // thought bubble
  ctx.beginPath();
  ctx.arc(W/2 + 50 + 20 * Math.sin(t), H/2 - 50 + 20 * Math.cos(t), 30, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.font = '16px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Thoughts', W/2 + 50 + 20 * Math.sin(t), H/2 - 50 + 20 * Math.cos(t));

  // brain waves
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 70);
  ctx.lineTo(W/2 + 50 * Math.sin(t), H - 20);
  ctx.stroke();

  ctx.restore();
}
